use vsdb::{L2, MapxRaw, MetricKind};
use vsdb_migrate::vecdex::migrate_v17;
#[test]
fn migrate_frozen_v17_graph_preserves_rows_ids_and_ann_results() {
    // Generated by the v17.0.21 implementation (da9a325), including its
    // saved metadata, every raw graph row, and the v17 query result.
    type Fixture = (Vec<u8>, Vec<(Vec<u8>, Vec<u8>)>, Vec<(u32, f32)>);
    let (meta, rows, hits): Fixture =
        postcard::from_bytes(include_bytes!("fixtures/vecdex-v17.postcard")).unwrap();
    vsdb::vsdb_configure(vsdb::VsdbOptions::new(
        std::env::temp_dir().join(format!("vsdb-vec-migrate-{}", rand::random::<u128>())),
    ))
    .unwrap();
    for dynamic in [false, true] {
        let mut store = MapxRaw::new();
        let id = store.instance_id();
        // Relocate the frozen fixture's one identity into this parallel test's
        // fresh prefix. All schema, row and graph bytes remain the original.
        let mut meta = meta.clone();
        let offset = meta.windows(8).position(|w| w == b"VSMAPX01").unwrap() + 8;
        meta[offset..offset + 8].copy_from_slice(&id.map_id.to_le_bytes());
        if dynamic {
            let magic = meta.windows(8).position(|w| w == b"VSTYPE03").unwrap();
            meta[magic..magic + 8].copy_from_slice(b"VSTYPE02");
            meta.insert(0, 0);
        }
        let mut batch = store.batch();
        for (key, value) in &rows {
            batch.insert(key, value);
        }
        batch.commit().unwrap();
        let path = store.namespace().meta_path(id.map_id);
        vsdb_core::common::create_dir_all_durable(path.parent().unwrap()).unwrap();
        vsdb_core::common::atomic_write_file(&path, &meta).unwrap();
        // Reject a malformed large length without changing earlier vectors.
        let (first, first_row) = rows.iter().find(|(k, _)| k[0] == 0).unwrap();
        let (last, last_row) = rows.iter().rfind(|(k, _)| k[0] == 0).unwrap();
        if dynamic {
            store.insert(last, [0xff; 12]);
            assert!(migrate_v17::<u32, MetricKind, f32>(id).is_err());
            assert_eq!(store.get(first).unwrap(), *first_row);
            assert!(store.get([6]).is_none());
            store.insert(last, last_row);

            // The first vector and durable cursor were published in the same
            // chunk before the simulated process interruption.
            let config = vsdb::HnswConfig {
                dim: 2,
                m: 2,
                m_max0: 3,
                ef_construction: 8,
                ef_search: 7,
            };
            let reference =
                vsdb::VecDexDyn::<u32>::new_with_metric(MetricKind::L2, config).unwrap();
            let schema = vsdb_migrate::raw_map(reference.instance_id())
                .unwrap()
                .get([6])
                .unwrap();
            let cursor = u64::from_be_bytes(first[1..].try_into().unwrap());
            let mut batch = store.batch();
            batch.insert(first, &first_row[1..]);
            batch.insert([7], postcard::to_allocvec(&(&schema, cursor)).unwrap());
            batch.commit_sync().unwrap();
            // Reverse values in old indices could use a different codec from
            // the stable forward key. The latter determines the converted row.
            let reverse = [&[3][..], &first[1..]].concat();
            store.insert(reverse, b"old-value-encoding");
        }
        let result = if dynamic {
            assert!(migrate_v17::<u32, L2, f32>(id).is_err());
            migrate_v17::<u32, MetricKind, f32>(id)
                .unwrap()
                .search(&[1.2, 0.6], 4)
                .unwrap()
        } else {
            assert!(migrate_v17::<u32, MetricKind, f32>(id).is_err());
            migrate_v17::<u32, L2, f32>(id).unwrap();
            // The rows were fenced but the old metadata survived a crash.
            vsdb::common::atomic_write_file(&path, &meta).unwrap();
            migrate_v17::<u32, L2, f32>(id)
                .unwrap()
                .search(&[1.2, 0.6], 4)
                .unwrap()
        };
        assert_eq!(result, hits);
        for (key, value) in &rows {
            match key[0] {
                0 => {
                    assert_eq!(store.get(key).unwrap().as_slice(), &value[1..]);
                }
                5 => {
                    let (ep, level, count, next, ef): (Option<u64>, u8, u64, u64, usize) =
                        postcard::from_bytes(value).unwrap();
                    let new = store.get(key).unwrap();
                    assert_eq!(new.len(), 34);
                    assert_eq!(&new[..2], &[ep.is_some() as u8, level]);
                    let nums: Vec<_> = new[2..]
                        .as_chunks::<8>()
                        .0
                        .iter()
                        .copied()
                        .map(u64::from_le_bytes)
                        .collect();
                    assert_eq!(nums, [ep.unwrap_or_default(), count, next, ef as u64]);
                }
                _ => assert_eq!(store.get(key).unwrap(), *value),
            }
        }
    }
}
